<template>
 <v-container fluid class="app-page alert-page">
  <AppPageHeader :title="t('Alerting / {section}', { section: t(sectionLabel) })" icon="mdi-bell-outline"><template #actions><v-btn variant="text" prepend-icon="mdi-help-circle-outline" class="help-button" @click="helpOpen=true">{{ t('How alerts work') }}</v-btn></template></AppPageHeader>
  <header class="app-page-heading"><div><h1 class="app-page-title">{{ t('Alerting') }}</h1><p>{{ t('Know when your growing system needs attention.') }}</p></div><div class="app-action-row"><v-btn variant="outlined" prepend-icon="mdi-refresh" :loading="loading" @click="load">{{ t('Refresh') }}</v-btn><v-btn v-if="settings.canManage && section==='rules'" color="primary" prepend-icon="mdi-plus" @click="editRule(null)">{{ t('New alert rule') }}</v-btn><v-btn v-if="settings.canManage && section==='contacts'" color="primary" prepend-icon="mdi-plus" @click="editContact(null)">{{ t('New contact point') }}</v-btn></div></header>
  <v-alert v-if="error" type="error" variant="tonal" class="mb-4">{{ t(error) }}</v-alert>
  <v-alert v-if="settings.monitor?.error" type="error" variant="tonal" class="my-4">{{ t(settings.monitor.error) }}</v-alert>
  <v-tabs :model-value="section" color="primary" height="44" class="alert-tabs" :aria-label="t('Alerting sections')"><v-tab value="rules" to="/alerting/rules">{{ t('Alert rules') }}</v-tab><v-tab v-if="settings.canManage" value="contacts" to="/alerting/contacts">{{ t('Contact points') }}</v-tab><v-tab value="silences" to="/alerting/silences">{{ t('Silences') }}</v-tab><v-tab value="history" to="/alerting/history">{{ t('History') }}</v-tab></v-tabs>
  <template v-if="section==='rules'">
   <div class="rule-toolbar">
    <div class="filter-field"><label for="alert-search">{{ t('Search alert rules') }}</label><v-text-field id="alert-search" v-model="search" :aria-label="t('Search alert rules')" :placeholder="t('Rule name, device or group')" prepend-inner-icon="mdi-magnify" variant="outlined" clearable hide-details /></div>
    <div class="filter-field"><label for="alert-severity">{{ t('Severity') }}</label><v-select id="alert-severity" v-model="severity" :aria-label="t('Severity')" :items="severityOptions" variant="outlined" hide-details /></div>
    <v-btn v-if="settings.canManage" variant="text" prepend-icon="mdi-book-open-outline" class="templates-button" @click="templatesOpen=true">{{ t('Templates') }}</v-btn>
   </div>
   <div class="state-filters" role="group" :aria-label="t('Filter rule states')"><button v-for="item in stateFilters" :key="item.label" type="button" :aria-pressed="state===item.label" @click="state=item.label">{{ t(item.label) }}<span>{{ item.count }}</span></button></div>
   <div class="summary-line"><span aria-live="polite">{{ t(filtered.length === 1 ? '{count} rule in this view' : '{count} rules in this view', { count: filtered.length }) }}</span><span>{{ t(settings.monitor?.running?'Live evaluation':'Monitor stopped') }} · {{ t(loading?'Refreshing…':'Updates every 15 sec') }}</span></div>
   <div class="app-panel rule-panel"><v-table class="rules-table" :aria-label="t('Alert rules')"><thead><tr><th>{{ t('State') }}</th><th>{{ t('Rule / target') }}</th><th>{{ t('Condition') }}</th><th>{{ t('Notifications') }}</th><th>{{ t('Details') }}</th></tr></thead>
    <tbody v-for="group in groups" :key="group.name"><tr class="group-row"><td colspan="5">{{ t(group.name) }}</td></tr><tr v-for="rule in group.rules" :key="rule.id" class="rule-row">
     <td><span class="state-badge" :class="`state-${rule.state.toLowerCase().replace(' ','-')}`">{{ t(rule.state) }}</span></td>
     <td><button type="button" class="rule-link" @click="detailId=rule.id">{{ rule.name }}</button><div class="meta">{{ rule.source.host }}<template v-if="rule.source.gpio!==undefined"> · GPIO {{ rule.source.gpio }}</template> · {{ t(rule.severity) }}</div></td>
     <td>{{ conditionText(rule) }}<div class="meta">{{ rule.pendingSeconds ? t('For {duration}', { duration: duration(rule.pendingSeconds) }) : t('No extra pending period') }}</div></td>
     <td><template v-if="isSilenced(rule.id)"><v-icon icon="mdi-bell-off-outline" size="15" class="mr-1" />{{ t('Silenced') }}<div class="meta">{{ t('Until {time}', { time: silenceEnd(rule.id) }) }}</div></template><template v-else>{{ notificationLabel(rule) }}<div v-if="notificationIssue(rule)" class="meta">{{ t(notificationIssue(rule)) }}</div></template></td>
     <td><div class="row-actions"><v-btn size="small" variant="text" @click="detailId=rule.id">{{ t('View') }}</v-btn><v-menu v-if="settings.canManage"><template #activator="{props}"><v-btn v-bind="props" icon="mdi-dots-horizontal" size="small" variant="text" :aria-label="t('Actions for {name}', { name: rule.name })" /></template><v-list density="compact"><v-list-item :title="t('Edit rule')" prepend-icon="mdi-pencil-outline" @click="editRule(rule)" /><v-list-item :title="t(rule.enabled?'Pause evaluation':'Resume evaluation')" :prepend-icon="rule.enabled?'mdi-pause':'mdi-play'" @click="toggleRule(rule)" /><v-list-item :title="t('Silence notifications')" prepend-icon="mdi-bell-off-outline" @click="openSilence(rule)" /><v-list-item :title="t('Delete rule')" prepend-icon="mdi-delete-outline" @click="confirmDelete('rules',rule)" /></v-list></v-menu></div></td>
    </tr></tbody></v-table>
    <div v-if="!filtered.length" class="rules-empty"><h2>{{ t(rules.length?'No matching rules':'No alert rules yet') }}</h2><p>{{ t(rules.length?'Try another search or clear the filters.':'Choose a template or create your first alert rule to start monitoring.') }}</p><v-btn v-if="!rules.length&&settings.canManage" variant="text" prepend-icon="mdi-book-open-outline" @click="templatesOpen=true">{{ t('Browse templates') }}</v-btn></div>
   </div><footer v-if="filtered.length>10" class="list-footer"><span>{{ t('{start}–{end} of {count} rules', { start: (page-1)*10+1, end: Math.min(page*10,filtered.length), count: filtered.length }) }}</span><v-pagination v-model="page" :length="Math.ceil(filtered.length/10)" :total-visible="5" /></footer>
  </template>
  <template v-else-if="section==='contacts'">
   <v-alert v-if="!settings.canManage" variant="tonal">{{ t('Only administrators can manage contact points.') }}</v-alert>
   <section v-else :aria-label="t('Contact points')" class="contact-section">
    <header class="section-top"><div><h2>{{ t('Contact points') }}</h2><p>{{ t('Choose where a firing or recovered alert should be reported.') }}</p></div></header>
    <article class="channel"><div class="channel-identity"><h3><v-icon icon="mdi-bell-outline" size="18" /> {{ t('In-app notifications') }}</h3><p>{{ t('Visible in Tomatoes. Rules keep evaluating when your browser is closed.') }}</p><span class="meta">{{ t('Always available · rule status and event history') }}</span></div><div class="channel-actions"><v-btn variant="outlined" @click="openPreview('inapp')">{{ t('Preview message') }}</v-btn></div></article>
    <article v-for="provider in providers" :key="provider.kind" class="channel" :data-channel="provider.kind">
     <div class="channel-identity"><h3><v-icon :icon="provider.icon" size="18" /> {{ t(provider.name) }}</h3><p v-if="!channelContacts(provider.kind).length">{{ t(provider.kind==='email'?'Recipient not set':'Recipient phone number not set') }}</p><span class="meta">{{ t(provider.ready?'Sender configured · contact must be enabled for delivery':'Setup required on the server') }}</span>
      <div v-for="contact in channelContacts(provider.kind)" :key="contact.id" class="saved-contact"><div><strong>{{ contact.name }}</strong><p>{{ contact.recipients.join(', ') }}</p><span class="meta">{{ t(contact.enabled?'Enabled':'Disabled') }}<template v-if="contact.kind==='whatsapp'"> · {{ contact.template }} · {{ contact.language }}</template></span></div><div class="contact-actions"><v-btn variant="text" size="small" @click="editContact(contact)">{{ t('Edit') }}</v-btn><v-btn variant="text" size="small" @click="openPreview(contact.kind,contact)">{{ t('Preview') }}</v-btn><v-btn variant="text" size="small" @click="confirmDelete('contacts',contact)">{{ t('Delete') }}</v-btn></div></div>
     </div><div class="channel-actions"><v-btn variant="outlined" @click="configureChannel(provider.kind)">{{ t(channelContacts(provider.kind).length?'Add contact':'Configure') }}</v-btn><v-btn variant="text" @click="openPreview(provider.kind)">{{ t('Preview message') }}</v-btn></div>
    </article>
    <div class="callout">{{ t('Group related alerts, send a recovery message and repeat unresolved alerts at a controlled interval. A silence mutes notifications; pausing a rule stops its evaluation.') }}</div>
   </section>
  </template>
  <template v-else-if="section==='silences'">
   <header class="section-top"><div><h2>{{ t('Silences') }}</h2><p>{{ t('Pause notifications for maintenance while rules keep evaluating.') }}</p></div><v-btn v-if="settings.canManage" variant="outlined" prepend-icon="mdi-bell-off-outline" :disabled="!rules.length" @click="openSilence(null)">{{ t('New silence') }}</v-btn></header>
   <article v-for="silence in silences" :key="silence.id" class="silence-item"><div><strong>{{ silence.ruleName }}</strong><p>{{ silence.reason }}</p><span class="meta">{{ t('Until {time}', { time: localizedDate(silence.ends_at) }) }} · {{ silence.actor }}</span></div><v-btn v-if="settings.canManage" variant="text" @click="mutate(()=>alertService.remove('silences',silence.id))">{{ t('End silence') }}</v-btn></article>
   <div v-if="!silences.length" class="compact-empty"><h3>{{ t('No active silences') }}</h3><p>{{ t('Use a silence during maintenance to keep monitoring without notifications.') }}</p></div>
  </template>
  <template v-else>
   <header class="section-top"><div><h2>{{ t('History') }}</h2><p>{{ t('State changes, notification attempts and maintenance actions.') }}</p></div><span class="meta">{{ t('Event history retained for 90 days') }}</span></header>
   <div v-if="history.length" class="history-list"><article v-for="entry in history" :key="entry.id" class="history-event"><time :datetime="new Date(entry.created_at).toISOString()" :title="localizedDate(entry.created_at)">{{ timeLabel(entry.created_at) }}<span>{{ dayLabel(entry.created_at) }}</span></time><div><strong>{{ entry.name }}</strong><p>{{ historyDescription(entry.description) }}</p></div><span class="history-kind">{{ t(entry.kind) }}</span></article></div>
   <div v-else class="compact-empty"><h3>{{ t('No events yet') }}</h3><p>{{ t('Rule activity will appear here.') }}</p></div>
   <div v-if="historyOffset||history.length===100" class="history-pagination"><v-btn :disabled="!historyOffset" variant="text" @click="historyOffset=Math.max(0,historyOffset-100);load()">{{ t('Newer events') }}</v-btn><v-btn :disabled="history.length<100" variant="text" @click="historyOffset+=100;load()">{{ t('Older events') }}</v-btn></div>
   <details v-if="settings.canManage" class="delivery-details"><summary>{{ t('Notification attempts') }} <span>{{ t('{count} recent', { count: deliveries.length }) }}</span></summary><p class="footnote">{{ t('Submitted means the provider accepted the request. Delivery and reading are not confirmed. Latest 100 attempts, retained for 30 days.') }}</p><div v-if="deliveries.length" class="history-list"><article v-for="entry in deliveries" :key="entry.id" class="history-event"><time :title="localizedDate(entry.created_at)">{{ timeLabel(entry.created_at) }}<span>{{ dayLabel(entry.created_at) }}</span></time><div><strong>{{ entry.recipient }}</strong><p>{{ t(entry.phase) }} · {{ t(entry.reason) }}</p><span class="meta">{{ t('{count} attempt(s)', { count: entry.attempts }) }}</span></div><span class="history-kind">{{ t(entry.status) }}</span></article></div><div v-else class="compact-empty"><p>{{ t('No external notification attempts yet.') }}</p></div></details>
  </template>
  <footer class="alert-footer"><span>Tomatoes v1.0.0</span><button type="button" @click="helpOpen=true"><i :class="['health-dot',settings.monitor?.running?'healthy':'']" />{{ t(settings.monitor?.running?'Monitor running':'Monitor stopped') }} · {{ t(settings.mqtt?.mqttConnected?'MQTT connected':'MQTT not connected') }}</button></footer>
  <v-dialog v-model="templatesOpen" max-width="680" scrollable><v-card><v-card-title>{{ t('Useful rule templates') }}</v-card-title><v-card-text><p class="mb-4 app-muted">{{ t('Choose a starting point. Adjust the target, limits and data source before enabling evaluation.') }}</p><div class="template-list"><div v-for="item in ruleTemplates" :key="item.kind"><div><strong>{{ t(item.title) }}</strong><p>{{ t(item.description) }}</p></div><v-btn variant="text" size="small" @click="useRuleTemplate(item.kind)">{{ t('Use') }}</v-btn></div></div></v-card-text><v-card-actions><v-spacer /><v-btn @click="templatesOpen=false">{{ t('Close') }}</v-btn></v-card-actions></v-card></v-dialog>
  <v-dialog v-model="helpOpen" max-width="660" scrollable><v-card><v-card-title>{{ t('How alerts work') }}</v-card-title><v-card-text><ol class="help-steps"><li><strong>{{ t('Read a signal.') }}</strong> {{ t('The backend checks device reports or an existing InfluxDB metric.') }}</li><li><strong>{{ t('Evaluate a rule.') }}</strong> {{ t('Choose a target, trigger limit, recovery limit and evaluation interval.') }}</li><li><strong>{{ t('Wait for persistence.') }}</strong> {{ t('A breach is Pending until it lasts for the pending period, then becomes Firing.') }}</li><li><strong>{{ t('Notify a contact point.') }}</strong> {{ t('Follow status in Tomatoes, or send email and WhatsApp after provider setup.') }}</li><li><strong>{{ t('Handle missing data.') }}</strong> {{ t('No data and Error are incidents, separate from Normal.') }}</li></ol><v-alert variant="tonal" color="secondary" class="my-5">{{ t('A silence mutes external notifications. Pause stops evaluation. Neither changes a GPIO or stops a pump.') }}</v-alert><p>{{ t('Rules run in the backend even with this page closed. Templates contain example limits; choose values for your crop and equipment.') }}</p><dl class="detail-grid mt-5"><dt>{{ t('Monitor') }}</dt><dd>{{ t(settings.monitor?.running?'Running':'Stopped') }}</dd><dt>MQTT</dt><dd>{{ t(settings.mqtt?.mqttConnected?'Connected':'Not connected') }}</dd><dt>InfluxDB</dt><dd>{{ t(settings.influxConfigured?'Configured':'Not configured') }}</dd><dt>{{ t('Last cycle') }}</dt><dd>{{ localizedDate(settings.monitor?.lastTick) }}</dd></dl></v-card-text><v-card-actions><v-spacer /><v-btn @click="helpOpen=false">{{ t('Close') }}</v-btn></v-card-actions></v-card></v-dialog>
  <RuleEditor v-if="ruleEditor" :initial="selectedRule" :initial-template="initialTemplate" :contacts="contacts" :devices="settings.devices||[]" @close="ruleEditor=false" @saved="ruleEditor=false;load()" />
  <NotificationPreview v-if="messagePreview" :kind="messagePreview.kind" :contact="messagePreview.contact" :rules="rules" @close="messagePreview=null" />
  <ContactEditor v-if="contactEditor" :initial="selectedContact" :initial-kind="contactKind" :settings="settings" @close="contactEditor=false" @saved="contactEditor=false;load()" />
  <v-dialog v-model="silenceDialog" max-width="600" persistent scrollable><v-card class="alert-dialog"><v-card-title>{{ t('New silence') }}</v-card-title><v-card-text><v-alert v-if="dialogError" type="error" variant="tonal" class="mb-4">{{ t(dialogError) }}</v-alert><v-form id="silence-form" @submit.prevent="saveSilence"><v-select v-model="silenceForm.ruleId" :label="t('Alert rule')" :items="rules" :item-title="silenceRuleLabel" item-value="id" variant="outlined" /><v-select v-model="silenceForm.minutes" :label="t('Duration')" :items="silenceDurations" variant="outlined" /><v-text-field v-if="silenceForm.minutes==='custom'" v-model="customMinutes" :label="t('Duration (minutes)')" min="1" max="10080" type="number" variant="outlined" /><v-text-field v-model="silenceForm.reason" :label="t('Reason')" :placeholder="t('For example: pump maintenance')" maxlength="200" variant="outlined" /><div class="callout">{{ t('Only external notifications are muted. The rule keeps evaluating, and Firing alerts remain visible.') }}</div></v-form></v-card-text><v-card-actions><v-spacer /><v-btn :disabled="saving" @click="silenceDialog=false">{{ t('Cancel') }}</v-btn><v-btn color="primary" variant="flat" form="silence-form" type="submit" :loading="saving">{{ t('Create silence') }}</v-btn></v-card-actions></v-card></v-dialog>
  <v-dialog :model-value="!!detail" max-width="680" scrollable @update:model-value="detailId=null"><v-card v-if="detail" class="alert-dialog"><v-card-title>{{ detail.name }}</v-card-title><v-card-text><div class="detail-status"><span class="state-badge" :class="`state-${detail.state.toLowerCase().replace(' ','-')}`">{{ t(detail.state) }}</span><span>{{ t(detail.severity) }} · {{ detail.source.host }}<template v-if="detail.source.gpio!==undefined"> · GPIO {{ detail.source.gpio }}</template></span></div><dl class="detail-facts"><div v-for="item in detailRows" :key="item[0]"><dt>{{ t(item[0]) }}</dt><dd>{{ item[1] }}</dd></div></dl><div class="callout">{{ t(detail.enabled?(detail.reason||'Waiting for evaluation.'):'Evaluation paused. The latest reading is kept for reference.') }}</div><h3 class="dialog-section-title">{{ t('What to check') }}</h3><p class="app-muted">{{ t(guidance(detail)) }}</p></v-card-text><v-card-actions class="detail-actions"><v-btn v-if="settings.canManage" @click="editRule(detail);detailId=null">{{ t('Edit rule') }}</v-btn><v-spacer /><template v-if="settings.canManage"><v-btn @click="toggleRule(detail)">{{ t(detail.enabled?'Pause':'Resume') }}</v-btn><v-btn variant="outlined" @click="openSilence(detail);detailId=null">{{ t('Silence') }}</v-btn></template><v-btn variant="outlined" @click="detailId=null">{{ t('Close') }}</v-btn></v-card-actions></v-card></v-dialog>
  <v-dialog :model-value="!!deletion" max-width="440" persistent><v-card><v-card-title>{{ t(deletion?.path === 'rules' ? 'Delete alert rule?' : 'Delete contact point?') }}</v-card-title><v-card-text>{{ t('{name} will be removed. This cannot be undone.', { name: deletion?.item.name }) }}<v-alert v-if="dialogError" type="error" variant="tonal" class="mt-3">{{ t(dialogError) }}</v-alert></v-card-text><v-card-actions><v-spacer /><v-btn :disabled="saving" @click="deletion=null">{{ t('Cancel') }}</v-btn><v-btn color="error" :loading="saving" @click="remove">{{ t('Delete') }}</v-btn></v-card-actions></v-card></v-dialog>
 </v-container>
</template>
<script setup lang="ts">
import { useLanguage } from '@/composables/useLanguage';
import { formatTime, formatDate } from '@/composables/dateTime.ts';
import AppPageHeader from '@/components/navigation/AppPageHeader.vue';
import { computed,onMounted,onUnmounted,ref,watch } from 'vue';
import { useRoute } from 'vue-router';
import { alertService,alertError,dateLabel,sourceLabel,ruleUnit } from '@/services/alertService';
import type { AlertEvent, AlertSettings, AlertState, Contact, ContactKind, Delivery, NotificationKind, Rule, Severity, Silence, SourceKind } from '@/services/alertService';
import RuleEditor from './RuleEditor.vue';
import ContactEditor from './ContactEditor.vue';
import NotificationPreview from './NotificationPreview.vue';

const { t } = useLanguage();
const route=useRoute(),section=computed(()=>route.path.split('/').at(-1) ?? '');
const sectionLabels: Record<string, string> = { rules: 'Alert rules', contacts: 'Contact points', silences: 'Silences', history: 'History' };
const severityOptions = computed(() => (['All', 'Critical', 'Warning'] as const).map(value => ({ title: t(value), value })));
const localizedDate = (value: number | null | undefined) => dateLabel(value, t('Never'));
function historyDescription(description: string) {
  const transition = /^(Normal|Pending|Firing|No data|Error|Paused) → (Normal|Pending|Firing|No data|Error|Paused)\. (.*)$/.exec(description);
  if (transition) return [t(transition[1]) + ' → ' + t(transition[2]) + '.', t(transition[3])].join(' ').trim();
  const silence = /^(\S+) silenced notifications for (\d+) minutes\. Evaluation continues\.$/.exec(description);
  if (silence) return t('{actor} silenced notifications for {minutes} minutes. Evaluation continues.', { actor: silence[1], minutes: silence[2] });
  const event = /^(\S+) (saved an enabled rule|saved a paused rule|deleted the rule|saved the contact point|deleted the contact point|ended the silence)\.$/.exec(description);
  return event ? t('{actor} ' + event[2] + '.', { actor: event[1] }) : t(description);
}
const silenceRuleLabel = (rule: Rule) => `${rule.name} · ${rule.source.host}`;
const settings=ref<Partial<AlertSettings>>({}),rules=ref<Rule[]>([]),contacts=ref<Contact[]>([]),silences=ref<Silence[]>([]);
const history=ref<AlertEvent[]>([]),deliveries=ref<Delivery[]>([]),loading=ref(false),error=ref('');
const search=ref(''),state=ref<AlertState | 'All'>('All'),severity=ref<Severity | 'All'>('All'),page=ref(1),historyOffset=ref(0);
const ruleEditor=ref(false),selectedRule=ref<Rule | null>(null),contactEditor=ref(false),selectedContact=ref<Contact | null>(null),detailId=ref<number | null>(null);
const silenceDialog=ref(false),silenceForm=ref<{ruleId: number | null; minutes: number | 'custom'; reason: string}>({ruleId:null,minutes:60,reason:''});
type Deletion = {path: 'rules' | 'contacts'; item: Pick<Rule | Contact, 'id' | 'name'>};
const dialogError=ref(''),saving=ref(false),deletion=ref<Deletion | null>(null);
let timer: ReturnType<typeof setInterval> | undefined;
let disposed=false;
const detail=computed(()=>rules.value.find(rule=>rule.id===detailId.value));
const detailRows=computed(()=>{const r=detail.value;if(!r)return [];return [['Condition',t('{condition} for {duration}', { condition: conditionText(r), duration: duration(r.pendingSeconds) })],['Recovery threshold',`${r.operator==='>'?'≤':'≥'} ${r.recovery} ${ruleUnit(r.source)}`],['Evaluation interval',t('Every {duration}', { duration: duration(r.intervalSeconds) })],['Current sample',reading(r)],['Source',sourceLabel(r.source, t)],['Notification',isSilenced(r.id)?t('Silenced; evaluation continues'):notificationLabel(r)],['Sample timestamp',localizedDate(r.sampleAt)],['Last evaluation',localizedDate(r.evaluatedAt)]];});
const guidance=(rule: Rule)=>({pump_driver:'Inspect the driver report and pump supply. The last pulse result persists until the next pulse. ACTIVE does not prove water flow.',device_age:'Check the device power supply, Wi-Fi and MQTT connection before changing schedules.',wifi:'Check antenna placement, obstructions and access-point coverage.',output_on:'Inspect the output and pump locally. A GPIO state does not prove water is flowing.',cpu_temperature:'Inspect cooling and workload. Confirm that Telegraf is collecting recent samples.',disk_usage:'Review filesystem usage, logs, backups and database retention.',metric_age:'Check the sensor topic, firmware publishing, MQTT connection and Telegraf collection. Age is based on the latest InfluxDB timestamp.',metric:'Check the sensor feed, hostname, measurement, numeric field and sample timestamps.'}[rule.source.kind]);
const messagePreview=ref<{kind: NotificationKind; contact: Contact | null} | null>(null);
const contactKind=ref<ContactKind>('email'),customMinutes=ref<number | string>(60);
const silenceDurations = computed(() => [{ title: t('15 minutes'), value: 15 }, { title: t('30 minutes'), value: 30 }, { title: t('1 hour'), value: 60 }, { title: t('4 hours'), value: 240 }, { title: t('Custom duration'), value: 'custom' }]);
const timeLabel=(value: number)=>formatTime(value);
const dayLabel=(value: number)=>formatDate(value);
const channelContacts=(kind: NotificationKind)=>contacts.value.filter(contact=>contact.kind===kind);
function configureChannel(kind: ContactKind){contactKind.value=kind;selectedContact.value=null;contactEditor.value=true;}
function openPreview(kind: NotificationKind, contact: Contact | null = null) {
  messagePreview.value = { kind, contact: contact ?? channelContacts(kind)[0] ?? null };
}
const helpOpen=ref(false),templatesOpen=ref(false),initialTemplate=ref<SourceKind>('device_age');
const sectionLabel=computed(()=>(sectionLabels[section.value]||'Alert rules'));
const ruleTemplates: {kind: SourceKind; title: string; description: string}[] = [
 {kind:'pump_driver',title:'Pump driver feedback',description:'Detect failed actuation, missing feedback, short circuit, overtemperature or absent pump supply.'},
 {kind:'device_age',title:'Device not responding',description:'Track the time since an ESP32 last replied to MQTT discovery.'},
 {kind:'wifi',title:'Weak Wi-Fi signal',description:'Watch the RSSI reported by a connected device.'},
 {kind:'output_on',title:'Output ON longer than expected',description:'Monitor observed GPIO ON duration. Does not confirm water flow.'},
 {kind:'cpu_temperature',title:'Raspberry Pi temperature high',description:'Use CPU temperature collected by the existing Telegraf input.'},
 {kind:'disk_usage',title:'Storage usage high',description:'Check disk usage for a specific host and filesystem path.'},
 {kind:'metric_age',title:'Telemetry missing',description:'Watch the age of the latest sample for an exact MQTT sensor topic.'},
 {kind:'metric',title:'Growing environment / sensor metric',description:'Use an existing pH, EC, water temperature or level feed. Requires a matching numeric measurement.'},
];
const category=(rule: Rule)=>['device_age','wifi'].includes(rule.source.kind)?'ESP32 & network':['output_on','pump_driver'].includes(rule.source.kind)?'Pump outputs':['cpu_temperature','disk_usage'].includes(rule.source.kind)?'Server health':'Growing environment';
const stateFilters=computed(()=>(['All','Firing','Pending','No data','Error','Normal','Paused'] as const).map(label=>({label,count:label==='All'?rules.value.length:rules.value.filter(rule=>rule.state===label).length})));
const filtered=computed(()=>rules.value.filter(rule=>(state.value==='All'||rule.state===state.value)&&(severity.value==='All'||rule.severity===severity.value)&&`${rule.name} ${rule.source.host} ${sourceLabel(rule.source, t)} ${t(category(rule))} ${sourceLabel(rule.source)} ${category(rule)}`.toLowerCase().includes((search.value||'').toLowerCase())).sort((a,b)=>['ESP32 & network','Pump outputs','Server health','Growing environment'].indexOf(category(a))-['ESP32 & network','Pump outputs','Server health','Growing environment'].indexOf(category(b))||a.id-b.id));
const groups=computed(()=>{const result: {name: string; rules: Rule[]}[]=[];for(const rule of pageRules.value){let group=result.find(item=>item.name===category(rule));if(!group){group={name:category(rule),rules:[]};result.push(group);}group.rules.push(rule);}return result;});
const duration=(seconds: number)=>seconds >= 3600 ? t('{count} hr', { count: Number((seconds / 3600).toFixed(1)) }) : seconds >= 60 ? t('{count} min', { count: Number((seconds / 60).toFixed(1)) }) : t('{count} sec', { count: seconds });
const silenceEnd=(id: number)=>localizedDate(Math.max(...silences.value.filter(item=>item.rule_id===id).map(item=>item.ends_at)));
const ruleContacts=(rule: Rule)=>contacts.value.filter(contact=>rule.contactIds.includes(contact.id));
function notificationLabel(rule: Rule){const kinds=[...new Set(ruleContacts(rule).map(contact=>contact.kind))];const external = kinds.map(kind => kind === 'email' ? t('Email') : 'WhatsApp'); if (!external.length && !settings.value.canManage && rule.contactIds.length) external.push(t('External')); return [t('In-app'), ...external].join(' + ');}
function notificationIssue(rule: Rule){const selected=ruleContacts(rule);if(selected.some(contact=>!contact.enabled))return 'Contact point disabled';if(selected.some(contact=>contact.kind==='email')&&!settings.value.email)return 'Email needs setup';if(selected.some(contact=>contact.kind==='whatsapp')&&!settings.value.whatsapp?.configured)return 'WhatsApp needs setup';return '';}
function useRuleTemplate(kind: SourceKind){templatesOpen.value=false;initialTemplate.value=kind;selectedRule.value=null;ruleEditor.value=true;}
const pageRules=computed(()=>filtered.value.slice((page.value-1)*10,page.value*10));
const providers=computed<{kind: ContactKind; name: string; icon: string; ready?: boolean}[]>(()=>[{kind:'email',name:'Email / Outlook',icon:'mdi-email-outline',ready:settings.value.email},{kind:'whatsapp',name:'WhatsApp',icon:'mdi-whatsapp',ready:settings.value.whatsapp?.configured}]);
const driverConditions = { failure: 'Failed actuation', missing: 'No driver feedback', short: 'Driver short circuit',
  temperature: 'Driver overtemperature', supply: 'Pump supply absent / low' };
function conditionText(rule: Rule) {
  if (rule.source.kind === 'pump_driver' && rule.operator === '>' && rule.threshold === 0.5) {
    return t(rule.source.condition ? driverConditions[rule.source.condition] : 'Driver condition detected');
  }
  return `${rule.operator} ${rule.threshold} ${ruleUnit(rule.source)}`;
}
const reading=(rule: Rule)=>rule.value===null?'—':`${Number(rule.value.toFixed(2))} ${ruleUnit(rule.source)}`;
const isSilenced=(id: number)=>silences.value.some(item=>item.rule_id===id&&item.ends_at>Date.now());
watch([search,state,severity],()=>{page.value=1;});watch(filtered,()=>{page.value=Math.min(page.value,Math.max(1,Math.ceil(filtered.value.length/10)));});
async function load(){if(loading.value||disposed)return;loading.value=true;try{const config=await alertService.get('settings');const result=await Promise.all([alertService.get('rules'),alertService.get('silences'),alertService.get('history',{offset:historyOffset.value}),config.canManage?alertService.get('contacts'):[],config.canManage?alertService.get('deliveries'):[]]);if(disposed)return;settings.value=config;[rules.value,silences.value,history.value,contacts.value,deliveries.value]=result;error.value='';}catch(issue){error.value=alertError(issue);}finally{loading.value=false;}}
function editRule(rule: Rule | null){initialTemplate.value='device_age';selectedRule.value=rule;ruleEditor.value=true;}
function editContact(contact: Contact | null){contactKind.value=contact?.kind||'email';selectedContact.value=contact;contactEditor.value=true;}
function openSilence(rule: Rule | null){dialogError.value='';customMinutes.value=60;silenceForm.value={ruleId:rule?.id||null,minutes:60,reason:''};silenceDialog.value=true;}
async function saveSilence(){saving.value=true;dialogError.value='';try{await alertService.saveSilence({...silenceForm.value,minutes:silenceForm.value.minutes==='custom'?customMinutes.value:silenceForm.value.minutes});silenceDialog.value=false;await load();}catch(issue){dialogError.value=alertError(issue);}finally{saving.value=false;}}
function toggleRule(rule: Rule) { return mutate(() => alertService.enabled(rule.id, !rule.enabled)); }
async function mutate(action: () => Promise<unknown>){try{await action();await load();}catch(issue){error.value=alertError(issue);}}
function confirmDelete(path: Deletion['path'], item: Deletion['item']){dialogError.value='';deletion.value={path,item};}
async function remove(){if(!deletion.value)return;saving.value=true;dialogError.value='';try{await alertService.remove(deletion.value.path,deletion.value.item.id);deletion.value=null;await load();}catch(issue){dialogError.value=alertError(issue);}finally{saving.value=false;}}
onMounted(()=>{load();timer=setInterval(load,15000);});onUnmounted(()=>{disposed=true;clearInterval(timer);});
</script>
